+import { useState, useMemo } from "react";
+import { useTasks, useCreateTask } from "@/hooks/useTasks";
+import { TaskCard } from "./TaskCard";
+import { TaskDetail } from "./TaskDetail";
+import { TaskForm } from "./TaskForm";
+import { Button } from "@/components/ui/button";
+import { Input } from "@/components/ui/input";
+import { Label } from "@/components/ui/label";
+import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
+import {
+  Select,
+  SelectContent,
+  SelectItem,
+  SelectTrigger,
+  SelectValue,
+} from "@/components/ui/select";
+import { Plus, Filter } from "lucide-react";
+import type { Task, TaskStatus, TaskPriority } from "@/types/api";
+
+const COLUMNS: { id: TaskStatus; label: string }[] = [
+  { id: "todo", label: "Todo" },
+  { id: "in_progress", label: "In Progress" },
+  { id: "blocked", label: "Blocked" },
+  { id: "done", label: "Done" },
+];
+
+interface TaskKanbanProps {
+  projectId: string;
+}
+
+export function TaskKanban({ projectId }: TaskKanbanProps) {
+  const [page] = useState(1);
+  const [pageSize] = useState(100);
+  const [priorityFilter, setPriorityFilter] = useState<string>("");
+  const [assigneeFilter, setAssigneeFilter] = useState<string>("");
+  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
+  const [showForm, setShowForm] = useState(false);
+  const [editingTask, setEditingTask] = useState<Task | null>(null);
+
+  const params = useMemo(() => ({
+    page,
+    page_size: pageSize,
+    ...(priorityFilter && { priority: priorityFilter }),
+    ...(assigneeFilter && { assignee_id: assigneeFilter }),
+  }), [page, pageSize, priorityFilter, assigneeFilter]);
+
+  const { data, isLoading } = useTasks(projectId, params);
+  const createMutation = useCreateTask();
+
+  const tasks = data?.items ?? [];
+
+  const tasksByStatus = useMemo(() => {
+    const map: Record<TaskStatus, Task[]> = { todo: [], in_progress: [], blocked: [], done: [] };
+    for (const t of tasks) {
+      if (map[t.status]) map[t.status].push(t);
+    }
+    return map;
+  }, [tasks]);
+
+  const handleCreate = async (data: Partial<Task>) => {
+    await createMutation.mutateAsync({ projectId, data });
+    setShowForm(false);
+  };
+
+  const handleCardClick = (task: Task) => {
+    setSelectedTask(task);
+  };
+
+  const handleFormOpenChange = (open: boolean) => {
+    setShowForm(open);
+    if (!open) setEditingTask(null);
+  };
+
+  return (
+    <div className="space-y-4">
+      <div className="flex items-center justify-between gap-4 flex-wrap">
+        <div className="flex items-center gap-3 flex-wrap">
+          <div className="flex items-center gap-2">
+            <Filter className="h-4 w-4 text-muted-foreground" />
+            <Select value={priorityFilter} onValueChange={setPriorityFilter}>
+              <SelectTrigger className="w-[130px]">
+                <SelectValue placeholder="Priority" />
+              </SelectTrigger>
+              <SelectContent>
+                <SelectItem value="all">All Priorities</SelectItem>
+                <SelectItem value="low">Low</SelectItem>
+                <SelectItem value="medium">Medium</SelectItem>
+                <SelectItem value="high">High</SelectItem>
+                <SelectItem value="critical">Critical</SelectItem>
+              </SelectContent>
+            </Select>
+          </div>
+          <div className="flex items-center gap-2">
+            <Input
+              placeholder="Assignee ID..."
+              className="w-[140px]"
+              value={assigneeFilter}
+              onChange={(e) => setAssigneeFilter(e.target.value)}
+            />
+          </div>
+        </div>
+        <Button onClick={() => setShowForm(true)}>
+          <Plus className="h-4 w-4 mr-1" />
+          New Task
+        </Button>
+      </div>
+
+      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
+        {COLUMNS.map((col) => {
+          const colTasks = tasksByStatus[col.id] ?? [];
+          return (
+            <div key={col.id} className="space-y-2">
+              <div className="flex items-center justify-between px-1">
+                <h3 className="font-semibold text-sm">{col.label}</h3>
+                <span className="text-xs text-muted-foreground bg-muted rounded-full px-2 py-0.5">
+                  {colTasks.length}
+                </span>
+              </div>
+              <div className="space-y-2 min-h-[100px]">
+                {isLoading ? (
+                  <p className="text-sm text-muted-foreground p-2">Loading...</p>
+                ) : colTasks.length === 0 ? (
+                  <p className="text-sm text-muted-foreground p-2">No tasks</p>
+                ) : (
+                  colTasks.map((task) => (
+                    <TaskCard
+                      key={task.id}
+                      task={task}
+                      onClick={() => handleCardClick(task)}
+                      isBlocked={col.id === "blocked"}
+                      blockedByCount={task.blocked_by.length}
+                    />
+                  ))
+                )}
+              </div>
+            </div>
+          );
+        })}
+      </div>
+
+      <TaskDetail
+        task={selectedTask}
+        open={!!selectedTask}
+        onOpenChange={(open) => { if (!open) setSelectedTask(null); }}
+      />
+
+      <TaskForm
+        open={showForm}
+        onOpenChange={handleFormOpenChange}
+        onSubmit={handleCreate}
+        isPending={createMutation.isPending}
+        mode="create"
+      />
