router = APIRouter(prefix="/api", tags=["rfqs"])


@router.get("/projects/{project_id}/rfqs", response_model=RFQListResponse)
def list_rfqs(
    project_id: uuid.UUID,
    _: User = Depends(get_current_user),
    db: Session = Depends(get_db),
    page: int = Query(default=1, ge=1),
    page_size: int = Query(default=20, ge=1, le=100),
) -> RFQListResponse:
    items, total, page, page_size = rfq_service.list_rfqs_service(
        db, project_id, page=page, page_size=page_size
    )
    return RFQListResponse(
        items=[RFQRead.model_validate(i) for i in items],
        total=total,
        page=page,
        page_size=page_size,
    )


@router.post("/projects/{project_id}/rfqs", response_model=RFQRead, status_code=status.HTTP_201_CREATED)
def create_rfq(
    project_id: uuid.UUID,
    body: RFQCreate,
    current_user: User = Depends(require_role(Role.PM)),
    db: Session = Depends(get_db),
) -> RFQRead:
    try:
        rfq = rfq_service.create_rfq_service(db, project_id, body.model_dump(), current_user.id)
        return RFQRead.model_validate(rfq)
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e)) from e


